 $('workspaceFootnote').textContent=account?'Your diagrams save automatically to your account. Export whenever you’re ready.':'Your diagrams stay on this device. Sign in to save them across devices.';
 $('workspaceInfo').textContent=(search||notation!=='all')?`${projects.length} of ${totals.diagrams} diagrams`:totals.diagrams?`${totals.diagrams} diagram${totals.diagrams===1?'':'s'} · your collection`:'Ready when you are';
 $('collectionHeading').textContent=search||notation!=='all'?'Matching diagrams':'All diagrams';
 $('continueStrip').hidden=!latest||dashboardTab==='templates';if(latest){$('continueProject').textContent=latest.model.title;$('continueTime').textContent='Edited '+dateLabel(latest.updatedAt);$('continueProject').onclick=()=>openProject(latest.id);$('continueAction').onclick=()=>openProject(latest.id);}
 $('railRecent').innerHTML=[...db.projects].sort((a,b)=>b.updatedAt-a.updatedAt).slice(0,3).map(p=>`<button data-recent="${p.id}" title="${escapeXML(p.model.title)}">${icon('file',13)}<span dir="auto">${escapeXML(p.model.title)}</span></button>`).join('')||'<p>Your next idea belongs here.</p>';
