 const newCard=`<button class="new-card" id="newCard" ${!projects.length&&(search||notation!=='all')?'hidden':''}><span class="new-card-icon">${icon('plus',23)}</span><b>A new idea belongs here</b><small>Create a diagram from scratch.<br>Make every connection your own.</small><span class="new-card-hint">START WITH A BLANK CANVAS ${icon('chevron',10)}</span></button>`;
 $('projectGrid').innerHTML=cards+newCard;$('projectGrid').classList.toggle('list-view',dashboardView==='list');$('emptyWorkspace').hidden=totals.diagrams>0||!!search||notation!=='all';
 $('newCard').onclick=()=>newProject();$('projectGrid').querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>{const p=db.projects.find(p=>p.id===b.dataset.share);if(p?.role&&p.role!=='owner')team.show(p.id);else showShare(p.id);});$('projectGrid').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openProject(b.dataset.open));
 $('projectGrid').querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>{const p=db.projects.find(p=>p.id===b.dataset.copy);if(p){const m=clone(p.model);m.title=(m.title+' copy').slice(0,80);newProject(m);toast('Diagram duplicated.');}});
 $('projectGrid').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeProject(b.dataset.delete));
