$('downloadBtn').onclick=async()=>{const button=$('downloadBtn'),f=format(),data=exportData(),base=filename();button.disabled=true;button.textContent='Preparing your file…';try{let blob;if(f==='pdf'){blob=new Blob([await vectorPDF(data,{paper:$('pdfPaper').value,orientation:$('pdfOrientation').value,mode:$('pdfMode').value})],{type:'application/pdf'});}else if(f==='svg')blob=new Blob([data.svg],{type:'image/svg+xml;charset=utf-8'});else{const dims=outputSize(data),doc=new DOMParser().parseFromString(data.svg,'image/svg+xml');doc.documentElement.setAttribute('width',dims.width);doc.documentElement.setAttribute('height',dims.height);const img=await imageFrom(new XMLSerializer().serializeToString(doc)),canvas=document.createElement('canvas');canvas.width=dims.width;canvas.height=dims.height;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Image rendering is unavailable in this browser.');if(f==='pdf'){ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);}ctx.drawImage(img,0,0,canvas.width,canvas.height);if(f==='png')blob=await canvasBlob(canvas,'image/png');else{const jpg=await canvasBlob(canvas,'image/jpeg',.96);blob=new Blob([makePDF(new Uint8Array(await jpg.arrayBuffer()),canvas.width,canvas.height)],{type:'application/pdf'});}canvas.width=canvas.height=1;}download(blob,base+'.'+f);toast(f.toUpperCase()+' includes your entire diagram.');$('exportDialog').close();}catch(error){toast(error.message||'Export failed. Please try again.',true);}finally{button.disabled=false;preview();}};
