function accountStatus(state,message=''){const active=db.projects.find(p=>p.id===activeId);if(active&&page==='editor'){model=active.model;if(!drag&&!document.activeElement?.matches?.('input,textarea,select'))render();applyPermissions();}if(cloud?.paused)offlineAccount=true;db.deletions=(db.deletions||[]).filter(p=>!p.deletedSynced);cloudState=db.projects.some(p=>p.conflict)?'conflict':state;cloudMessage=message;cacheWorkspace();if(message)toast(message,true);}
