function finishAccount(){
 ready=true;$('accountLoading').hidden=true;accountBadge();
 if(!(loaded.readError&&!cloud))cacheWorkspace();
 const first=!shortcutsApplied;
 routingMuted=true;
 try{
  if(first&&routeParams().get('new')==='1'){
   showWorkspace();
   shortcutsApplied=true;
   newProject();
  }else{
   restoreRoute();
   shortcutsApplied=true;
  }
 }finally{routingMuted=false;}
 routingReady=true;
 syncRoute(true);
 team?.checkInvitation();
}
async function initializeAccount(){
 ready=false;$('accountLoading').hidden=false;$('retryAccount').hidden=true;
 try{
  if(navigator.onLine===false)throw Error('You are offline.');
  const data=await api('',{signal:AbortSignal.timeout(8000)});account=data.user;offlineAccount=false;
  if(account){
   cacheKey='bosha-account-'+account.id;rememberAccount();const restored=cachedAccountWorkspace(localStorage);const cached=restored?.db;
   const deletedIds=new Set((cached?.deletions||[]).map(p=>p.id)),projects=data.projects.filter(p=>!deletedIds.has(p.id));
   for(const p of projects)p.baseModel=clone(p.model);
   for(const p of cached?.projects||[]){if(!p.unsynced)continue;const index=projects.findIndex(s=>s.id===p.id);if(index>=0){if(projects[index].revision!==p.revision)p.conflict=true;projects[index]=p;}else if(!p.revision)projects.push(p);else{p.conflict=true;projects.push(p);}}
   db={version:2,projects:projects.slice(0,60),activeId:null,deletions:cached?.deletions||[]};activeId=cached?.activeId&&db.projects.some(p=>p.id===cached.activeId)?cached.activeId:null;db.activeId=activeId;model=db.projects.find(p=>p.id===activeId)?.model||blankDiagram();cloud=new CloudWorkspace(account,accountStatus,{onMerge:rebaseHistory});cloudState='saved';restorePending();
  }else{cloud=null;cloudState='guest';cacheKey=WORKSPACE_KEY;try{localStorage.removeItem(LAST_ACCOUNT);localVersions=JSON.parse(localStorage.getItem('bosha-local-versions')||'{}');}catch{localVersions={};}}
  finishAccount();if(loaded.migrated&&!account)persist(false);
 }catch(error){
  const cached=cachedAccountWorkspace(localStorage);offlineAccount=true;
  if(cached){account=cached.user;db=cached.db;activeId=db.activeId;model=db.projects.find(p=>p.id===activeId)?.model||blankDiagram();cacheKey='bosha-account-'+account.id;cloud=new CloudWorkspace(account,accountStatus,{paused:true,onMerge:rebaseHistory});restorePending();cloudState=db.projects.some(p=>p.conflict)?'conflict':'offline';}
  else{account=null;cloud=null;cloudState='guest';cacheKey=WORKSPACE_KEY;}
  finishAccount();toast(account?'Opened your local account copy. Reconnect to the same account to sync.':'Cloud storage is unavailable. You can keep drawing on this device.');
 }
}
async function reconnectAccount(){
 if(reconnecting)return;reconnecting=true;saveLabel();
 try{
  if(navigator.onLine===false)throw Error('Reconnect to the internet first.');
  if(!account){await initializeAccount();return;}
  const data=await api('',{signal:AbortSignal.timeout(8000)});
  if(data.user?.id!==account.id)throw Error('Sign in to the same account to sync this local workspace. Your edits have been kept on this device.');
  offlineAccount=false;cloud.paused=false;rememberAccount();await cloud.flush();cloudState=db.projects.some(p=>p.conflict)?'conflict':cloud.pending.size?'offline':'saved';cacheWorkspace();renderDashboard();
 }catch(error){offlineAccount=true;if(cloud)cloud.paused=true;cloudState=account?'offline':'guest';toast(error.message,true);}
 finally{reconnecting=false;saveLabel();}
}
