async function shareRequest(projectId,method='GET',body){const response=await fetch('/api/shares/'+encodeURIComponent(projectId),{method,credentials:'same-origin',signal:AbortSignal.timeout(12000),headers:{'Content-Type':'application/json','X-Bosha-Account-ID':account?.id||''},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error||'Sharing is unavailable.');return data;}
