async function showShare(projectId){sharingProject=projectId;$('shareControls').hidden=true;$('shareSignIn').hidden=!!account;$('shareStatus').textContent=account?'Loading sharing settings…':'Sign in and sync this diagram to create a read-only link.';$('shareDialog').showModal();if(!account)return;try{if(offlineAccount||cloud?.paused||navigator.onLine===false)throw Error('Reconnect your account before managing share links.');await cloud.flush();const p=db.projects.find(p=>p.id===projectId);if(!p||p.unsynced||p.conflict||!p.revision)throw Error('Sync this diagram and resolve any conflicts before sharing.');const data=await shareRequest(projectId);if(sharingProject!==projectId)return;renderSharing(data);$('shareControls').hidden=false;}catch(error){if(sharingProject===projectId)$('shareStatus').textContent=error.message;}}
$('shareBtn').onclick=()=>{const p=db.projects.find(p=>p.id===activeId);if(p?.role&&p.role!=='owner')team.show(activeId);else showShare(activeId);};
async function changeSharing(method){const projectId=sharingProject;const buttons=[$('createShare'),$('revokeShare')];buttons.forEach(b=>b.disabled=true);try{if(offlineAccount||cloud?.paused)throw Error('Reconnect your account to manage this link.');const data=await shareRequest(projectId,method,method==='POST'?{days:Number($('shareExpiry').value)}:null);if(sharingProject!==projectId)return;renderSharing(method==='DELETE'?{enabled:false,token:null}:data);toast(method==='DELETE'?'Share link revoked.':'Read-only link created.');}catch(error){if(sharingProject===projectId)$('shareStatus').textContent=error.message;}finally{buttons.forEach(b=>b.disabled=false);}}
$('createShare').onclick=()=>changeSharing('POST');$('revokeShare').onclick=()=>changeSharing('DELETE');
$('copyShareLink').onclick=async()=>{try{await navigator.clipboard.writeText($('shareLinkInput').value);toast('Share link copied.');}catch{$('shareLinkInput').select();toast('Select and copy the link from this field.');}};

team=setupCollaboration({context:()=>({ready,user:account,online:!offlineAccount&&!cloud?.paused&&navigator.onLine!==false,page,project:db.projects.find(p=>p.id===activeId),projects:db.projects,selected,camera,sharingProject,canReceive:!drag&&!cloud?.busy&&!cloud?.pending.size&&!db.projects.find(p=>p.id===activeId)?.unsynced&&!document.activeElement?.matches?.('input,textarea,select'),flush:async()=>{await cloud?.flush();}}),onRole:role=>{const p=db.projects.find(p=>p.id===activeId);if(p){p.role=role;applyPermissions();}},onRemote:p=>{const current=db.projects.find(q=>q.id===p.id);if(!current||current.unsynced||cloud?.busy||cloud?.pending.size||drag)return;if(p.revision!==current.revision){const notation=notationOf(model);Object.assign(current,p,{baseModel:clone(p.model)});model=current.model;model.notation=notation;restoreLayout(model);history.clear();if(!model.nodes.some(n=>n.id===selected)&&!model.edges.some(e=>e.id===selected)){selected=null;selectionSet.clear();}render();cacheWorkspace();}else{current.role=p.role;applyPermissions();}},onJoin:async pid=>{await initializeAccount();openProject(pid);team.refresh();},onLocate:elementId=>{const n=model.nodes.find(n=>n.id===elementId)||model.nodes.find(n=>n.id===model.edges.find(e=>e.id===elementId)?.source);if(!n){toast('This element has been removed.');return;}selected=elementId;selectionSet.clear();camera.x=n.x-W/camera.scale/2;camera.y=n.y-H/camera.scale/2;view();render();},toast});
$('teamSignIn').onclick=()=>{$('teamDialog').close();showAccount();};
$('discardTeamInvite').onclick=()=>{team.dismissInvitation();$('teamDialog').close();window.location.hash='';};
svg.addEventListener('pointermove',event=>{try{const p=point(event);team.setPointer({x:p.x,y:p.y});}catch{}});svg.addEventListener('pointerleave',()=>team.setPointer({x:null,y:null}));
if(ready)team.checkInvitation();
